#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────


# Production setup for the daily Reminder (docs/specs/016-daily-reminder.md, ADR 0005).
# Run from the repo root, after ./scripts/setup-production.sh: ./scripts/setup-reminders.sh
# Needs: gh (logged in), Node 24 + pnpm. It reuses the public values that wizard remembered.
# Private values (the push key, the scheduler secret) are never written to disk: they go straight
# to Vercel and to Supabase's Vault, so an interrupted run generates fresh ones.

ENV_FILE=".setup-production.env"
VERCEL_CLI="vercel@65.0.0"         # keep in step with .github/workflows/deploy.yml

TOTAL_STAGES=5

if ! command -v gh >/dev/null 2>&1 || ! gh auth status >/dev/null 2>&1; then
  printf '\n  gh (GitHub CLI) must be installed and logged in first: gh auth login\n\n'
  exit 1
fi
# The public values the first wizard remembers. If its file is not here (another checkout, or a
# clean one), recover them: the Sydney project's reference is fixed, and the production URL is the
# GitHub variable that wizard set.
SUPABASE_REF_DEFAULT="xrfbpeiugmacbossropu"   # calories-counter, ap-southeast-2 (Sydney)
SUPABASE_PROJECT_REF=$(_existing SUPABASE_PROJECT_REF || true)
SUPABASE_PROJECT_REF="${SUPABASE_PROJECT_REF:-$SUPABASE_REF_DEFAULT}"
PRODUCTION_URL=$(_existing PRODUCTION_URL || true)
[[ -n "$PRODUCTION_URL" ]] || PRODUCTION_URL=$(gh variable get PRODUCTION_URL 2>/dev/null || true)
if [[ -z "$PRODUCTION_URL" ]]; then
  printf '\n  Run ./scripts/setup-production.sh first: it records the production URL.\n\n'
  exit 1
fi

# copy_to_clipboard TEXT puts TEXT on the clipboard, so a secret never has to be printed.
copy_to_clipboard() {
  if   command -v clip.exe >/dev/null 2>&1; then printf '%s' "$1" | clip.exe
  elif command -v pbcopy   >/dev/null 2>&1; then printf '%s' "$1" | pbcopy
  elif command -v wl-copy  >/dev/null 2>&1; then printf '%s' "$1" | wl-copy
  elif command -v xclip    >/dev/null 2>&1; then printf '%s' "$1" | xclip -selection clipboard
  else return 1; fi
}

banner "Calories Counter: daily Reminder setup"

# ── 1. Keys the app and the scheduler share ────────────────────────────────
stage "Generate the push key and the scheduler secret"
GENERATE=1
if [[ -n "$(_existing REMINDER_KEYS_SET || true)" ]]; then
  warn "The push key and scheduler secret are already in Vercel from an earlier run."
  note "Replacing the push key switches off every phone's Reminder until it is turned on again."
  confirm "Generate new ones anyway?" || GENERATE=0
fi
if (( GENERATE )); then
  keys=$(node -e 'const k=require("web-push").generateVAPIDKeys();console.log(JSON.stringify(k))')
  NEXT_PUBLIC_VAPID_PUBLIC_KEY=$(node -pe 'JSON.parse(process.argv[1]).publicKey' "$keys")
  VAPID_PRIVATE_KEY=$(node -pe 'JSON.parse(process.argv[1]).privateKey' "$keys")
  REMINDER_SECRET=$(node -e 'console.log(require("crypto").randomBytes(32).toString("hex"))')
  say "Generated a push key pair and a 64-character scheduler secret."
  note "They are kept in memory only, and sent to Vercel and Supabase in the next stages."
  say ""
  say "Push services contact this address if something is wrong with the app's messages."
  ask VAPID_SUBJECT_EMAIL "Your email address:"
  VAPID_SUBJECT="mailto:${VAPID_SUBJECT_EMAIL}"
fi

# ── 2. Supabase: the secret key the send route uses ────────────────────────
stage "Supabase: secret key"
if (( GENERATE )); then
  say "The send route reads every User's due Reminders, which row level security hides from the"
  say "publishable key. It uses the project's secret key, and only ever on the server."
  open_url "https://supabase.com/dashboard/project/${SUPABASE_PROJECT_REF}/settings/api-keys"
  step "On the API Keys page, reveal the Secret key (starts sb_secret_) and copy it."
  ask_secret SUPABASE_SECRET_KEY "Paste the secret key:"
  [[ "$SUPABASE_SECRET_KEY" == sb_secret_* ]] || warn "That doesn't start with sb_secret_. Check it before continuing."
else
  note "Skipped: not replacing the keys."
fi

# ── 3. Vercel: the app's environment variables ─────────────────────────────
stage "Vercel: production environment variables"
if (( GENERATE )); then
  say "Needs a Vercel token, and the project IDs the first wizard remembered."
  open_url "https://vercel.com/account/tokens"
  step "Use the same token as the Deploy workflow's VERCEL_TOKEN, or create a new one."
  ask_secret VERCEL_TOKEN "Paste the Vercel token:"
  VERCEL_ORG_ID=$(_existing VERCEL_ORG_ID || true)
  VERCEL_PROJECT_ID=$(_existing VERCEL_PROJECT_ID || true)
  if [[ -z "$VERCEL_ORG_ID" || -z "$VERCEL_PROJECT_ID" ]]; then
    say ""
    say "The Vercel CLI needs to know which project to change."
    open_url "https://vercel.com/dashboard"
    step "Open the project → Settings → General, and copy 'Project ID' (starts prj_)."
    ask VERCEL_PROJECT_ID "Paste the Project ID:"
    step "Open your team (or account) Settings → General, and copy the 'ID' / 'Team ID'."
    ask VERCEL_ORG_ID "Paste the Team/Account ID:"
    write_env VERCEL_PROJECT_ID "$VERCEL_PROJECT_ID"
    write_env VERCEL_ORG_ID "$VERCEL_ORG_ID"
  fi
  export VERCEL_ORG_ID VERCEL_PROJECT_ID
  failed=0
  add_vercel_env() {
    local name="$1" value="$2"
    # A variable that already exists is replaced, so an old key and a new one never mix.
    pnpm dlx "$VERCEL_CLI" env rm "$name" production --yes --token "$VERCEL_TOKEN" >/dev/null 2>&1 || true
    if printf '%s' "$value" | pnpm dlx "$VERCEL_CLI" env add "$name" production --token "$VERCEL_TOKEN" >/dev/null 2>&1; then
      printf '  %s✓ set%s %s in Vercel production\n' "$GREEN" "$RESET" "$name"
    else
      failed=1
      SKIPPED+=("Vercel env $name (Project → Settings → Environment Variables, Production)")
      warn "couldn't set $name"
    fi
  }
  add_vercel_env SUPABASE_SECRET_KEY "$SUPABASE_SECRET_KEY"
  add_vercel_env REMINDER_SECRET "$REMINDER_SECRET"
  add_vercel_env VAPID_PRIVATE_KEY "$VAPID_PRIVATE_KEY"
  add_vercel_env VAPID_SUBJECT "$VAPID_SUBJECT"
  add_vercel_env NEXT_PUBLIC_VAPID_PUBLIC_KEY "$NEXT_PUBLIC_VAPID_PUBLIC_KEY"
  if (( failed == 0 )); then
    write_env REMINDER_KEYS_SET "yes"
    write_env NEXT_PUBLIC_VAPID_PUBLIC_KEY "$NEXT_PUBLIC_VAPID_PUBLIC_KEY"
  fi
else
  note "Skipped: not replacing the keys."
fi

# ── 4. Supabase: tell the scheduler where to call, and the secret ──────────
stage "Supabase: Vault secrets for the scheduler"
if (( GENERATE )); then
  say "The database job (every 15 minutes) reads the app's address and the scheduler secret from Vault."
  SEND_URL="${PRODUCTION_URL}/api/reminders/send"
  VAULT_SQL="do \$\$
declare existing uuid;
begin
  select id into existing from vault.secrets where name = 'reminder_url';
  if existing is null then perform vault.create_secret('${SEND_URL}', 'reminder_url');
  else perform vault.update_secret(existing, '${SEND_URL}'); end if;

  select id into existing from vault.secrets where name = 'reminder_secret';
  if existing is null then perform vault.create_secret('${REMINDER_SECRET}', 'reminder_secret');
  else perform vault.update_secret(existing, '${REMINDER_SECRET}'); end if;
end \$\$;"
  open_url "https://supabase.com/dashboard/project/${SUPABASE_PROJECT_REF}/sql/new"
  if copy_to_clipboard "$VAULT_SQL"; then
    step "Paste (Ctrl/Cmd-V) into the SQL editor. The SQL is already on your clipboard."
  else
    step "Paste this into the SQL editor:"
    printf '\n%s\n\n' "$VAULT_SQL"
  fi
  step "Click Run. It should say 'Success. No rows returned'."
  pause "Done? Press Enter."
  warn "Clear your clipboard now: it held the scheduler secret."
else
  note "Skipped: not replacing the keys."
fi

# ── 5. Deploy and check ────────────────────────────────────────────────────
stage "Deploy and check"
say "The push key is built into the app, so it needs a new deploy to take effect."
step "Push any commit to main, or re-run the latest 'Deploy' run in GitHub Actions."
open_url "$(gh repo view --json url --jq .url)/actions/workflows/deploy.yml"
pause "Wait for the deploy to finish, then press Enter."
say ""
say "Checking the send route is there and locked:"
code=$(curl --silent --output /dev/null --write-out '%{http_code}' --max-time 15 -X POST "${PRODUCTION_URL}/api/reminders/send" || true)
if [[ "$code" == "401" ]]; then
  printf '  %s✓%s refuses a call without the secret (401)\n' "$GREEN" "$RESET"
else
  printf '  %s✗%s expected 401 without the secret, got %s\n' "$RED" "$RESET" "${code:-no answer}"
  SKIPPED+=("The send route did not answer 401. Check the deploy finished and the variables are set.")
fi
if (( GENERATE )); then
  code=$(curl --silent --output /dev/null --write-out '%{http_code}' --max-time 15 -X POST \
    -H "x-scheduler-secret: ${REMINDER_SECRET}" "${PRODUCTION_URL}/api/reminders/send" || true)
  if [[ "$code" == "200" ]]; then
    printf '  %s✓%s accepts the scheduler secret (200)\n' "$GREEN" "$RESET"
  else
    printf '  %s✗%s expected 200 with the secret, got %s\n' "$RED" "$RESET" "${code:-no answer}"
    SKIPPED+=("The send route did not accept the secret (got ${code:-no answer}). Check the Vercel variables.")
  fi
fi
say ""
note "To watch the job, run this in the Supabase SQL editor:"
note "  select start_time, status, return_message from cron.job_run_details order by start_time desc limit 5;"
note "and  select status_code, created from net._http_response order by created desc limit 5;"

finish
